//
// GENERATOR_VERSION follows the generated bytes. Each version's output, at the
// FICTIONAL example record, hashes to one entry below, with the version stamp itself
// normalised out (it is in the bytes, so it would otherwise always "change"). The test
// fails both ways:
//   - the output changed but GENERATOR_VERSION didn't: bump it and add an entry;
//   - GENERATOR_VERSION was bumped but the output didn't change: the bump says nothing.
// Version 1 is the output of main before the bump (ba6e2dc). The 2026-10-26 programs
// were also stamped v1 but came from an earlier commit: the stamp's gap that this closes.

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import { GENERATOR_VERSION, generatePrograms, readSetup, runsTemplate } from './programs.mjs';
import { generatePlanes, planesRunsTemplate } from './programs-planes.mjs';

/** Normalised output hash per version. Append; never edit an entry. */
const OUTPUT_HASHES = {
  1: 'd16f2297e9758c0635841bced87e1f207d708d6efa39c2be0e210e6b08ea882c',
  2: '0e11c45744f89bff9f0c16330f498114a6a3c992a57159112f270dfb6c222329',
};

const HERE = dirname(fileURLToPath(import.meta.url));
const EXAMPLE = readFileSync(
  join(HERE, '../../packages/db-schema/examples/example-router.json'),
  'utf8',
);
const MASSO = EXAMPLE.replace('"dialect": "generic"', '"dialect": "masso-g3-5.13"');
const OPTS = { envelopeX: 1000, envelopeY: 800 };

/** Every byte both generators write (programs and runs files), version stamp removed. */
export function outputHash() {
  const s = readSetup(MASSO, OPTS);
  const programs = generatePrograms(s, { events: true });
  const planes = generatePlanes(s);
  const files = [
    ...programs.map((p) => p.gcode),
    JSON.stringify(runsTemplate(s, programs)),
    ...planes.map((p) => p.gcode),
    JSON.stringify(planesRunsTemplate(s, planes)),
  ].map((t) =>
    t.replace(/Generator v\d+/g, 'Generator v#').replace(/"generator":\d+/g, '"generator":0'),
  );
  return createHash('sha256').update(files.join('\0')).digest('hex');
}

describe('GENERATOR_VERSION', () => {
  const now = outputHash();
  it('names an entry, and that entry is this output', () => {
    assert.ok(OUTPUT_HASHES[GENERATOR_VERSION], `no entry for version ${GENERATOR_VERSION}`);
    assert.equal(
      now,
      OUTPUT_HASHES[GENERATOR_VERSION],
      'the generated output changed: bump GENERATOR_VERSION and add its hash',
    );
  });
  it('is the newest entry, and no two entries are the same output', () => {
    const versions = Object.keys(OUTPUT_HASHES).map(Number);
    assert.equal(GENERATOR_VERSION, Math.max(...versions));
    const hashes = Object.values(OUTPUT_HASHES);
    assert.equal(
      new Set(hashes).size,
      hashes.length,
      'two versions with the same output: a bump with nothing changed',
    );
  });
});
